Here is the commit message:
scsi: pm8001: Fix use-after-free in pm8001_queue_command()

Commit e29c47fe8946 ("scsi: pm8001: Simplify pm8001_task_exec()") refactors
pm8001_queue_command(), however it introduces a potential cause of a double
free scenario when it changes the function to return -ENODEV in case of phy
down/device gone state.

In this path, pm8001_queue_command() updates task status and calls
task_done to indicate to upper layer that the task has been handled.
However, this also frees the underlying SAS task. A -ENODEV is then
returned to the caller. When libsas sas_ata_qc_issue() receives this error
value, it assumes the task wasn't handled/queued by LLDD and proceeds to
clean up and free the task again, resulting in a double free.

Since pm8001_queue_command() handles the SAS task in this case, it should
return 0 to the caller indicating that the task has been handled.

Fixes: e29c47fe8946 ("scsi: pm8001: Simplify pm8001_task_exec()")
Signed-off-by: Salomon Dushimirimana <salomondush@google.com>
Reviewed-by: Damien Le Moal <dlemoal@kernel.org>
Link: https://patch.msgid.link/20260213192806.439432-1-salomondush@google.com
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
In pm8001_queue_command(), when the device is in a phy down/gone state, the function calls task_done() to complete the SAS task (which frees it) but then returns -ENODEV. The caller (libsas) interprets a non-zero return as the task not being handled, so it proceeds to clean up and free the task again, resulting in a use-after-free/double free.

Here is the patch:
   */
 int pm8001_queue_command(struct sas_task *task, gfp_t gfp_flags)
 {
 	struct task_status_struct *ts = &task->task_status;
 	enum sas_protocol task_proto = task->task_proto;
 	struct domain_device *dev = task->dev;
 	struct pm8001_device *pm8001_dev = dev->lldd_dev;
 	bool internal_abort = sas_is_internal_abort(task);
 	struct pm8001_hba_info *pm8001_ha;
 	struct pm8001_port *port;
 	struct pm8001_ccb_info *ccb;
 	unsigned long flags;
 	u32 n_elem = 0;
 	int rc = 0;

 	if (!internal_abort && !dev->port) {
 		ts->resp = SAS_TASK_UNDELIVERED;
 		ts->stat = SAS_PHY_DOWN;
 		if (dev->dev_type != SAS_SATA_DEV)
 			task->task_done(task);
 		return 0;
 	}

 	pm8001_ha = pm8001_find_ha_by_dev(dev);
 	if (pm8001_ha->controller_fatal_error) {
 		ts->resp = SAS_TASK_UNDELIVERED;
 		task->task_done(task);
 		return 0;
 	}

 	pm8001_dbg(pm8001_ha, IO, "pm8001_task_exec device\n");

 	spin_lock_irqsave(&pm8001_ha->lock, flags);

 	port = dev->port->lldd_port;

 	if (!internal_abort &&
 	    (DEV_IS_GONE(pm8001_dev) || !port || !port->port_attached)) {
 		ts->resp = SAS_TASK_UNDELIVERED;
 		ts->stat = SAS_PHY_DOWN;
 		if (sas_protocol_ata(task_proto)) {
 			spin_unlock_irqrestore(&pm8001_ha->lock, flags);
 			task->task_done(task);
 			spin_lock_irqsave(&pm8001_ha->lock, flags);
 		} else {
 			task->task_done(task);
 		}
-		rc = -ENODEV;
-		goto err_out;
+		spin_unlock_irqrestore(&pm8001_ha->lock, flags);
+		pm8001_dbg(pm8001_ha, IO, "pm8001_task_exec device gone\n");
+		return 0;
 	}

 	ccb = pm8001_ccb_alloc(pm8001_ha, pm8001_dev, task);
 	if (!ccb) {
 		rc = -SAS_QUEUE_FULL;
 		goto err_out;
 	}

 	if (!sas_protocol_ata(task_proto)) {
 		if (task->num_scatter) {
 			n_elem = dma_map_sg(pm8001_ha->dev, task->scatter,
 					    task->num_scatter, task->data_dir);
 			if (!n_elem) {
 				rc = -ENOMEM;
 				goto err_out_ccb;
 			}
 		}
 	} else {
 		n_elem = task->num_scatter;
 	}

 	task->lldd_task = ccb;
 	ccb->n_elem = n_elem;

 	atomic_inc(&pm8001_dev->running_req);

 	rc = pm8001_deliver_command(pm8001_ha, ccb);
 	if (rc) {
 		atomic_dec(&pm8001_dev->running_req);
 		if (!sas_protocol_ata(task_proto) && n_elem)
 			dma_unmap_sg(pm8001_ha->dev, task->scatter,
 				     task->num_scatter, task->data_dir);
 err_out_ccb:
 		pm8001_ccb_free(pm8001_ha, ccb);

 err_out:
 		pm8001_dbg(pm8001_ha, IO, "pm8001_task_exec failed[%d]!\n", rc);
 	}

 	spin_unlock_irqrestore(&pm8001_ha->lock, flags);

 	return rc;
 }



